add('cor:c8-gram (proof, mixed lengths)',
    'Append the graded expansion for families containing two lengths.',
    'inner_product_checks.json C1; inner_product_design.tex eq:ip-graded.',
    r"""For the outer direction, the change $-aX_0$ requires the change $-\bar aY_0$ on the right side, while Proposition \ref{prop:c8-laws} gives $+aY_0$; hence $\bar a=-a$.""",
    r"""For the outer direction, the change $-aX_0$ requires the change $-\bar aY_0$ on the right side, while Proposition \ref{prop:c8-laws} gives $+aY_0$; hence $\bar a=-a$. On a family containing lengths $L$ and $L+1$ the tree norms are of relative order (unit)$^{L-2}$; in a basis normalised by the tree norms the relation is expanded in the square root of the unit: $Y_{\frac12}=X_{\frac12}^{\rm adj}+\big[Y_0,\mathrm{Gram}_{\rm tree}^{-1}\mathrm{Gram}_{\frac12}\big]$ and $Y_1=X_1^{\rm adj}+\big[Y_0,\mathrm{Gram}_{\rm tree}^{-1}\mathrm{Gram}_1\big]+\big[X_{\frac12}^{\rm adj},\mathrm{Gram}_{\rm tree}^{-1}\mathrm{Gram}_{\frac12}\big]-\mathrm{Gram}_{\rm tree}^{-1}\mathrm{Gram}_{\frac12}\big[Y_0,\mathrm{Gram}_{\rm tree}^{-1}\mathrm{Gram}_{\frac12}\big]$, with $X_{\frac12}$ the classical length-increasing part and $\mathrm{Gram}_{\frac12}$ the entries between the two lengths of order one half.""",
    ['QS-4'])
add('cor:c8-gram (last sentence, real part of the outer direction)',
    '"The conjugation fixes the real part of the outer direction" overstates what the radial relation does: on the pair (xi, xi^dagger) the free multiple of S^(1)(xi) '
    'in the arity-one finite counterterm (restriction of G_B and of the exact inner cocycle along R_xi) shifts Q_1 and S_1 with one pattern, and a real part '
    'shifts the radial lines; it is fixed by reflection compatibility, which relates the counterterm along S_+ (x) W to its Theta_n image along S_- (x) W^*.',
    'step2/qa/ip_audit2_targets-plan/ip_audit2_checks.json A1, A2; odd_components_design.tex rem:o-alpha, rem:o-GBdagger; engine_plan.json open item "Re a expected to be fixed by the Q^dagger = S test"; '
    'inner_product_checks.json C16 (real reflection-compatible rescalings: r_Q = r_P/2; real B excluded, imaginary B allowed); inner_product_design.tex prop:ip-realpart.',
    r"""which is also the condition for $aG_B$ to be reflection compatible, $B$ anticommuting with $\dagger_n$: the conjugation fixes the real part of the outer direction.""",
    r"""which is also the condition for $aG_B$ to be reflection compatible, $B$ anticommuting with $\dagger_n$: reflection compatibility (Theorem \ref{thm:c8-fields}) fixes the real part of the outer direction, since the arity-one finite counterterm along $S_-\otimes W^*$ must be the $\Theta_n$-image of the one along $S_+\otimes W$.""",
    ['TP-1'])
doc = {'file': 'step2/qa/ch08_corrections_from_ip.json',
       'target': 'manuscript/ch08_definitions.tex (not edited; corrections proposed)',
       'source': 'step2/theory/inner_product_design.tex (revision 2026-10-29) and step2/qa/ip_findings_disposition.json',
       'verification': 'every old_text occurs exactly once in the current chapter (checked by this script)',
       'corrections': C}
json.dump(doc, open(os.path.join(HERE, 'ch08_corrections_from_ip.json'), 'w'), indent=1, ensure_ascii=False)
print('corrections:', len(C))
